#!/usr/bin/env node
/**
 * Behavioural check of the 50 self-contained hand-off copies in review/top50/.
 *
 *   npm i --no-save linkedom
 *   node tools/handoff-smoke.mjs
 *
 * These are the files a reviewer actually opens (single file, CSS + JS inlined,
 * assets bundled), and they are generated by a different code path than
 * pages/<id>/index.html — so they need their own check. A syntax error in the
 * inlined bundle does not throw a visible error: the page still paints its
 * eight sections, but every [data-reveal] stays at opacity:0, so the visitor
 * sees eight empty blocks. That is exactly the failure this tool exists for.
 *
 * Per page:
 *   - every inline <script> parses as JavaScript, then executes without error
 *   - one theme control, flips both ways, keeps aria-pressed in sync
 *   - mobile menu opens and closes
 *   - every [data-reveal] gets .is-in / .in
 *   - every element a `.js … {opacity:0}` rule hides ends up revealed
 *   - each of the eight slots is present once, in order, with real text
 *   - count-ups match their locked data-count
 *   - every local asset reference resolves on disk from review/
 *
 * Writes review/handoff-smoke.json. Behavioural only: no layout engine.
 */
import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const COMPOSITOR = path.resolve(__dirname, '..');
const REVIEW = path.join(COMPOSITOR, 'review');
const topArg = process.argv.indexOf('--top');
const TOP = topArg !== -1 ? path.resolve(process.argv[topArg + 1]) : path.join(REVIEW, 'top50');

let parseHTML;
try {
  ({ parseHTML } = await import('linkedom'));
} catch (e) {
  console.error('linkedom is not installed.\n  npm i --no-save linkedom\n  node tools/handoff-smoke.mjs');
  process.exit(2);
}

const ORDER = ['header', 'hero', 'delivery', 'financial', 'why', 'work', 'cta', 'footer'];
const MIN_TEXT = 60;

/* ---------------------------------------------------------------- CSS rules
   Collect the `.js …{opacity:0}` declarations from the page's inlined <style>.
   These are the only rules that can hide static content until script runs. */
function revealGatedSelectors(css) {
  const out = [];
  const noComments = css.replace(/\/\*[\s\S]*?\*\//g, '');
  const stack = [];
  let buf = '';
  for (let i = 0; i < noComments.length; i++) {
    const ch = noComments[i];
    if (ch === '{') {
      stack.push(buf.trim());
      buf = '';
    } else if (ch === '}') {
      const decls = buf;
      const selector = stack.pop() || '';
      buf = '';
      const insideKeyframes = stack.some((s) => /^@(-[a-z]+-)?keyframes/i.test(s));
      if (!insideKeyframes && /opacity\s*:\s*0(?![.\d])/.test(decls) && !/animation\s*:/.test(decls)) {
        for (const part of selector.split(',')) {
          const sel = part.trim();
          if (!/^\.js\b/.test(sel)) continue;
          if (/\b(:hover|:focus|:active)\b/.test(sel)) continue;
          out.push(sel.replace(/^\.js\s*/, ''));
        }
      }
    } else {
      buf += ch;
    }
  }
  return out;
}

function boot(html) {
  const { window, document } = parseHTML(html);
  const errors = [];
  const queue = [];
  let clock = 0;
  const store = new Map();
  const IO = class {
    constructor(cb) { this.cb = cb; }
    observe(el) { queue.push(() => this.cb([{ isIntersecting: true, target: el }], this)); }
    unobserve() {}
    disconnect() {}
  };
  const sandbox = {
    document,
    location: { search: '', href: 'http://local/page/', origin: 'http://local', pathname: '/page/' },
    matchMedia: () => ({ matches: false, addEventListener() {}, addListener() {} }),
    localStorage: { getItem: (k) => (store.has(k) ? store.get(k) : null), setItem: (k, v) => store.set(k, String(v)) },
    IntersectionObserver: IO,
    requestAnimationFrame: (cb) => { queue.push(() => cb((clock += 16))); return 1; },
    setTimeout: (fn) => { queue.push(fn); return 0; },
    clearTimeout() {},
    addEventListener() {},
    getComputedStyle: () => ({ getPropertyValue: () => '' }),
    CSS: { escape: (s) => String(s).replace(/[^\w-]/g, '\\$&') },
    Image: class { set src(v) { this._src = v; if (this.onload) queue.push(() => this.onload()); } get src() { return this._src; } },
    Intl,
    URLSearchParams,
    URL,
    console,
    parent: { postMessage() {} },
    Event: window.Event,
  };
  sandbox.window = sandbox;
  const ctx = vm.createContext(sandbox);
  ctx.window = ctx;

  const blocks = [...html.matchAll(/<script(?![^>]*application\/json)(?![^>]*src=)[^>]*>([\s\S]*?)<\/script>/g)].map((m) => m[1]);
  let parsed = 0;
  for (const code of blocks) {
    if (!code.trim()) continue;
    try { new vm.Script(code); parsed++; } catch (e) { errors.push('syntax: ' + e.message); }
  }
  if (parsed !== blocks.filter((b) => b.trim()).length) {
    // do not execute a bundle whose parse already failed; run the rest anyway
  }
  for (const code of blocks) {
    if (!code.trim()) continue;
    try { vm.runInContext(code, ctx); } catch (e) { if (errors.length < 4) errors.push('script: ' + e.message); }
  }
  for (let i = 0; i < 8000 && queue.length; i++) {
    try { queue.shift()(); } catch (e) { if (errors.length < 4) errors.push('task: ' + e.message); }
  }
  return { window, document, errors, blocks: blocks.filter((b) => b.trim()).length, parsed };
}

const dirs = fs.existsSync(TOP)
  ? fs.readdirSync(TOP).filter((d) => fs.existsSync(path.join(TOP, d, 'index.html'))).sort()
  : [];

const failures = [];
const fail = (id, msg) => failures.push(`${id}: ${msg}`);
const stats = { pages: 0, scripts: 0, reveals: 0, hidden_rules: 0, hidden_elements: 0 };

for (const d of dirs) {
  const file = path.join(TOP, d, 'index.html');
  const html = fs.readFileSync(file, 'utf8');
  stats.pages++;

  const { window, document, errors, blocks, parsed } = boot(html);
  stats.scripts += blocks;
  if (errors.length) fail(d, errors.slice(0, 2).join(' / '));
  if (parsed !== blocks) fail(d, `${blocks - parsed}/${blocks} inline scripts fail to parse`);

  /* eight slots, once each, in the fixed order */
  const roots = [...document.querySelectorAll('[data-slot]')];
  const seen = [];
  for (const r of roots) {
    const s = r.getAttribute('data-slot');
    if (!seen.includes(s)) seen.push(s);
  }
  if (seen.join(',') !== ORDER.join(',')) fail(d, `slot order ${seen.join(',') || 'none'}`);

  for (const slot of ORDER) {
    const root = document.querySelector(`[data-slot="${slot}"]`);
    if (!root) { fail(d, `missing slot ${slot}`); continue; }
    const text = root.textContent.replace(/\s+/g, ' ').trim();
    if (text.length < MIN_TEXT) fail(d, `slot ${slot} has ${text.length} chars of text`);
  }

  /* theme control */
  const toggles = document.querySelectorAll('[data-theme-toggle]');
  if (toggles.length !== 1) fail(d, `theme controls=${toggles.length}`);
  else {
    const root = document.documentElement;
    const before = root.getAttribute('data-theme');
    if (before !== 'light' && before !== 'dark') fail(d, `data-theme=${before}`);
    toggles[0].dispatchEvent(new window.Event('click'));
    const after = root.getAttribute('data-theme');
    if (after === before || after !== (before === 'dark' ? 'light' : 'dark')) fail(d, `theme ${before}->${after}`);
    else if (toggles[0].getAttribute('aria-pressed') !== String(after === 'dark')) fail(d, 'aria-pressed');
  }

  /* mobile menu */
  const btn = document.querySelector('[data-slot="header"] .nav__toggle');
  if (btn) {
    const id = btn.getAttribute('aria-controls');
    const panel = id ? document.getElementById(id) : null;
    if (panel) {
      btn.dispatchEvent(new window.Event('click'));
      if (btn.getAttribute('aria-expanded') !== 'true' || panel.hidden) fail(d, 'menu open');
      btn.dispatchEvent(new window.Event('click'));
      if (btn.getAttribute('aria-expanded') !== 'false' || !panel.hidden) fail(d, 'menu close');
    }
  }

  /* reveals: every [data-reveal] must have been un-hidden */
  const reveals = [...document.querySelectorAll('[data-reveal]')];
  stats.reveals += reveals.length;
  const stuck = reveals.filter((el) => !el.classList.contains('is-in') && !el.classList.contains('in'));
  if (stuck.length) fail(d, `${stuck.length}/${reveals.length} [data-reveal] still hidden`);

  /* every element hidden by a `.js` opacity:0 rule must now sit inside .is-in */
  const css = [...html.matchAll(/<style[^>]*>([\s\S]*?)<\/style>/g)].map((m) => m[1]).join('\n');
  let hiddenCount = 0;
  let stillHidden = [];
  for (const sel of revealGatedSelectors(css)) {
    let matches = [];
    try { matches = [...document.querySelectorAll(sel)]; } catch (e) { continue; }
    stats.hidden_rules++;
    for (const el of matches) {
      hiddenCount++;
      if (!el.closest('.is-in, .in')) stillHidden.push(sel);
    }
  }
  stats.hidden_elements += hiddenCount;
  if (stillHidden.length) fail(d, `${stillHidden.length} element(s) left at opacity:0 (${[...new Set(stillHidden)].slice(0, 2).join(' | ')})`);

  /* count-ups */
  for (const el of document.querySelectorAll('[data-count]')) {
    const got = el.textContent.replace(/[^\d]/g, '');
    if (got !== String(Number(el.getAttribute('data-count')))) {
      fail(d, `count-up ${got} != ${el.getAttribute('data-count')}`);
      break;
    }
  }

  /* local assets resolve */
  for (const m of html.matchAll(/(?:src|href)="([^"#?]+)"/g)) {
    const ref = m[1];
    if (/^(https?:|mailto:|data:|javascript:)/.test(ref) || ref.startsWith('#')) continue;
    // absolute site routes (/product, /pricing …) are the original marketing
    // paths, not files of this static export; verify.mjs tracks them separately.
    if (ref.startsWith('/')) continue;
    if (ref === 'top50.html' || /^[a-z]+:/i.test(ref)) continue;
    const abs = path.resolve(path.dirname(file), ref.split('?')[0]);
    if (!fs.existsSync(abs) && !fs.existsSync(path.join(abs, 'index.html')) && !ref.endsWith('/')) {
      fail(d, `missing asset ${ref}`);
    }
  }
}

const report = {
  tool: 'tools/handoff-smoke.mjs',
  dom: 'linkedom (no layout engine)',
  pages_checked: stats.pages,
  inline_scripts: stats.scripts,
  reveals_checked: stats.reveals,
  opacity_rules_checked: stats.hidden_rules,
  hidden_elements_checked: stats.hidden_elements,
  failures: failures.length,
  examples: failures.slice(0, 10),
  gate: stats.pages === 50 && failures.length === 0 ? 'PASS' : 'FAIL',
  source: path.relative(COMPOSITOR, TOP),
};
fs.mkdirSync(REVIEW, { recursive: true });
fs.writeFileSync(path.join(REVIEW, 'handoff-smoke.json'), JSON.stringify(report, null, 2) + '\n');

console.log('## HAND-OFF SMOKE (self-contained review/top50 copies)');
console.log(`pages: ${stats.pages}/50 · inline scripts: ${stats.scripts} · reveals: ${stats.reveals} · opacity-gated elements: ${stats.hidden_elements}`);
console.log(`failures: ${failures.length}`);
for (const f of failures.slice(0, 12)) console.log('  ' + f);
console.log(`gate: ${report.gate}`);
process.exit(report.gate === 'PASS' ? 0 : 1);
